import {esc,cash,icon,categorySymbol,pageHead,row,field,btn,empty,dateLabel} from './ui.js';
import {getSummary,budgetCategoryKey} from './model.js';
import {budgetSuggestions,normalizeSavingsHack} from './savings-parity-model.js';
import {renderSavingsHackDisclosure} from './savings-hack-disclosure.js';
const today=()=>new Date().toISOString().slice(0,10),future=n=>new Date(Date.now()+n*86400000).toISOString().slice(0,10);
const money=v=>Math.round(Number(v)*100),key=()=>globalThis.crypto?.randomUUID?.()||String(Date.now());
const ruleMoney=value=>{const text=String(value).trim();return /^(?:\d+|\d*\.\d{1,2})$/.test(text)?Math.round(Number(text)*100):NaN;};
const actionButton=(label,action,id='',secondary=true)=>`<button class="button ${secondary?'secondary':''}" data-parity="${action}" data-id="${esc(id)}">${label}</button>`;
const title=h=>({percent:'Percentage of payments',fixed:'After each payment',roundup:'Spare change',income:'When money comes in',scheduled:`${h.frequency||'Weekly'} saving`,none:'No saving rule'})[h?.type||'none'];
export const planningMoney=(ctx,value,options={})=>ctx.state.settings?.hideBalance?'••••.••':cash(value,options);
export function planningSheet(ctx, html, bind, options) {
  return ctx.sheet(`<div class="planning-sheet">${html}</div>`, bind, options);
}
export function openHackEditor(ctx,box,{setup=false}={}){
  const h={type:'none',value:100,...(box.hack||{})};
  const html=`<h2>Let the little things add up.</h2><p>Choose a rule for ${esc(box.name||'your box')}. Your plan and recovery needs always come first.</p><form class="form-stack" id="parity-hack-form"><label class="planning-rule-label" for="saving-rule-type"><span>Saving rule</span><span class="planning-rule-choice"><select id="saving-rule-type" name="type" aria-describedby="saving-rule-help">${[['none','No rule for now'],['percent','A percentage when I pay'],['fixed','A little extra when I pay'],['roundup','Round up my payments'],['income','A percentage when money arrives'],['scheduled','Save on a schedule']].map(([v,t])=>`<option value="${v}" ${h.type===v?'selected':''}>${t}</option>`).join('')}</select><span class="planning-rule-chevron" aria-hidden="true">${icon('chevron',18)}</span></span><small id="saving-rule-help" class="planning-rule-help">Tap to choose a saving rule.</small></label><div data-hack-value>${field({label:'Amount (GH₵), or percentage for percentage rules',name:'value',type:'number',value:['percent','income'].includes(h.type)?h.value:(h.value/100).toFixed(2),min:'0.01',max:'100000',required:true})}</div><div data-hack-schedule><label class="planning-rule-label" for="saving-rule-frequency"><span>How often?</span><span class="planning-rule-choice"><select id="saving-rule-frequency" name="frequency">${['daily','weekly','monthly'].map(v=>`<option value="${v}" ${h.frequency===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select><span class="planning-rule-chevron" aria-hidden="true">${icon('chevron',18)}</span></span></label>${field({label:'Next date',name:'nextRun',type:'date',value:h.nextRun||future(1),min:today()})}</div><details><summary>My saving limits</summary><div class="form-stack" style="margin-top:14px">${field({label:'Maximum saved each month (GH₵, 0 means no extra cap)',name:'cap',type:'number',min:'0',value:(h.monthlyCap||0)/100})}${field({label:'Keep at least this in Everyday (GH₵)',name:'floor',type:'number',min:'0',value:(h.floor||0)/100})}</div></details>${renderSavingsHackDisclosure()}<p class="error" role="alert"></p><button class="button" type="submit">${setup?'Use this rule':'Save my rule'}</button></form>`;
  planningSheet(ctx, html,el=>{
    const form=el.querySelector('form'),type=form.elements.type;
    const sync=()=>{el.querySelector('[data-hack-value]').hidden=type.value==='none';el.querySelector('[data-hack-schedule]').hidden=type.value!=='scheduled';form.elements.value.required=type.value!=='none';form.elements.value.max=['percent','income'].includes(type.value)?'100':'100000';};type.onchange=sync;sync();
    form.onsubmit=e=>{
      e.preventDefault();const v=type.value,percentage=['percent','income'].includes(v);
      const proposal={type:v,value:v==='none'?0:percentage?Number(form.elements.value.value):ruleMoney(form.elements.value.value),monthlyCap:ruleMoney(form.elements.cap.value||'0'),floor:ruleMoney(form.elements.floor.value||'0')};
      if(v==='scheduled'){proposal.frequency=form.elements.frequency.value;proposal.nextRun=form.elements.nextRun.value;}
      // Editing a paused rule changes its details; only Resume should switch it on.
      if(h.paused!==undefined)proposal.paused=h.paused;
      if(h.lastRun)proposal.lastRun=h.lastRun;
      const hack=normalizeSavingsHack(proposal);
      if(!hack){el.querySelector('.error').textContent=percentage?'Use a percentage above 0 and up to 100, and valid saving limits.':'Check the saving amount, limits and next date. Use amounts with up to two decimal places.';return;}
      // Validate the complete rule before touching either a setup draft or saved Box.
      if(setup){box.hack=hack;ctx.saveDraft?.();ctx.closeSheet();ctx.refresh();return;}
      const result=hack.type==='none'&&box.hack?.type!=='none'?ctx.act('cancelSavingsHack',{id:box.id}):ctx.act('updateBox',{id:box.id,hack});
      if(!result.ok){el.querySelector('.error').textContent=result.message;return;}
      ctx.closeSheet();ctx.refresh();ctx.toast('Saving rule updated. Small moves, your way.');
    };
  });
}
export function planningParityLinks(ctx,section){
  return section==='boxes'?`<details class="planning-details"><summary>Savings options</summary><div class="planning-tools">${actionButton('All saving rules','hacks')}${actionButton('Archived boxes','archives')}<button type="button" class="text-button" data-action="p:hack-explain">About Savings Hacks</button></div></details>`:`<details class="planning-details"><summary>More planning tools</summary><div class="planning-list">${row({emoji:icon('calendar',20),title:'Budget periods',sub:'Review a period. Start the next one.',action:'parity-periods'})}${row({emoji:icon('chat',20),title:'Talk me through my budget',sub:'One question at a time.',action:'parity-guided'})}${row({emoji:icon('plan',20),title:'Category habits',sub:'Remember choices and correct a payment.',action:'parity-categories'})}</div></details>`;
}

export function renderPlanningParity(ctx,r){
  const s=ctx.state;
  if(r.section==='boxes'&&r.page==='hacks'){
    const boxes=s.boxes.filter(b=>!b.archived&&b.hack?.type&&b.hack.type!=='none'),month=today().slice(0,7),saved=(s.savingsHistory||[]).filter(e=>e.status==='saved'&&e.at.startsWith(month)).reduce((n,e)=>n+e.amount,0);
    return `<section class="page">${pageHead('Your saving rules')}<div class="content"><div class="planning-hero"><span class="muted">Saved this month</span><div class="amount-xl accent">${planningMoney(ctx,saved)}</div></div>${boxes.length?`<div class="panel planning-list">${boxes.map(b=>row({emoji:b.emoji,title:b.name,sub:`${title(b.hack)} · ${b.hack.paused?'Paused':'Active'}${b.hack.type==='scheduled'?` · Next ${dateLabel(b.hack.nextRun)}`:''}`,action:`parity-rule-${b.id}`})).join('')}</div>`:empty({emoji:icon('repeat',28),title:'A little habit. A growing goal.',body:'Open a Money Box and choose a saving rule.'})}<div class="planning-main-action">${actionButton('Check scheduled savings','run-schedules','',false)}</div><p class="planning-help">Local simulation. Scheduled rules run when checked in this browser. Missed dates are not charged repeatedly.</p><details class="planning-details"><summary>Rule activity</summary><div class="planning-list">${(s.savingsHistory||[]).slice(0,40).map(e=>row({emoji:icon(e.status==='saved'?'check':'clock',20),title:`${s.boxes.find(b=>b.id===e.boxId)?.name||'Money Box'} · ${e.status}`,sub:`${e.reason} · ${dateLabel(e.at)}`,right:e.amount?planningMoney(ctx,e.amount):''})).join('')||'<p class="muted planning-help">No rule activity yet. Saved and skipped moves will appear here.</p>'}</div></details></div></section>`;
  }
  if(r.section==='boxes'&&r.page==='archive')return `<section class="page">${pageHead('Archived boxes')}<div class="content"><p class="muted">Their money and history stay yours. Restore a box to move money or save again.</p><div class="panel">${s.boxes.filter(b=>b.archived).map(b=>row({emoji:b.emoji,title:b.name,sub:`${planningMoney(ctx,b.balance)} kept in savings`,right:'Restore',action:`parity-restore-${b.id}`})).join('')||'<p class="muted" style="padding:18px">No archived boxes yet.</p>'}</div></div></section>`;
  if(r.section==='boxes'&&r.page==='transfer'){
    const t=s.transactions.find(t=>t.id===r.id&&t.boxTransfer);if(!t)return null;
    return `<section class="page task-page">${pageHead('Box transfer')}<div class="content"><p class="eyebrow">${esc(t.status)} · Local simulation</p><h1 class="large-question">${planningMoney(ctx,t.amount)}</h1><p>${esc(t.merchant)} · ${t.type==='saving'?'Everyday → Money Box':'Money Box → Everyday'}</p><div class="panel">${row({title:'Reference',sub:t.id})}${row({title:'Status',right:t.status})}${row({title:'Attempt',right:String(t.attempt||1)})}</div><p class="muted">${t.status==='pending'?'Your money is held. Checking alone does not confirm it.':t.status==='failed'?'No money left the source. Retry keeps the same reference.':t.status==='reversed'?'The money was returned once.':'Your transfer is confirmed.'}</p>${t.status==='pending'?`<div class="stack">${actionButton('Check status','transfer-check',t.id)}${actionButton('Simulate confirmed','transfer-success',t.id,false)}${actionButton('Simulate failed','transfer-failed',t.id)}</div>`:t.status==='failed'?actionButton('Retry this transfer','transfer-retry',t.id,false):''}${['pending','success'].includes(t.status)?actionButton('Simulate reversal','transfer-reverse',t.id):''}</div><div class="bottom-action">${actionButton('Back to my box','transfer-box',t.boxId,false)}</div></section>`;
  }
  if(r.section==='plan'&&r.page==='periods'){
    const b=s.budget;return `<section class="page">${pageHead('Budget periods')}<div class="content">${b.created?`<div class="section-label"><h2>Current period</h2></div><div class="panel planning-list">${row({emoji:icon('calendar',20),title:`${dateLabel(b.startDate)} – ${dateLabel(b.endDate)}`})}${row({title:'Planned',right:planningMoney(ctx,b.items.reduce((n,i)=>n+i.amount,0))})}${row({title:'Used',right:planningMoney(ctx,b.items.reduce((n,i)=>n+i.spent,0))})}</div><div class="planning-main-action">${actionButton('Review and start next period','new-period','',false)}</div><details class="planning-details"><summary>Current period options</summary>${actionButton('Archive current period','archive-period')}</details>`:'<p class="muted">No active budget. Reuse a saved period or create your first plan.</p>'}<div class="section-label"><h2>Previous periods</h2></div><div class="panel planning-list">${(s.budgetHistory||[]).map(p=>row({emoji:icon('plan',20),title:`${dateLabel(p.startDate)} – ${dateLabel(p.endDate)}`,sub:`Planned ${planningMoney(ctx,p.totalPlanned)} · Used ${planningMoney(ctx,p.totalSpent)}`,right:'Review',action:`parity-period-${p.periodId}`})).join('')||'<p class="planning-help">Finished periods will appear here.</p>'}</div></div></section>`;
  }
  if(r.section==='plan'&&r.page==='guided'){
    const d=ctx.draft.plan||(ctx.draft.plan={items:[],item:{}}),g=d.guide||(d.guide={step:'name',name:'',rateText:'',frequency:'weekly',due:s.income.nextDate||future(14)});
    const question={name:'First, what must your money cover?',rate:`How much for ${esc(g.name)}?`,frequency:'How often will you need that?',due:'Until when should we cover it?'}[g.step]||'What must your money cover?';
    const input=g.step==='name'?field({label:'Your essential',name:'name',value:g.name,placeholder:'Food & groceries',required:true}):g.step==='rate'?field({label:'Amount each time (GH₵)',name:'rate',type:'number',value:g.rateText,min:'.01',required:true}):g.step==='frequency'?`<label>How often?<select name="frequency">${[['daily','Each day'],['weekly','Each week'],['once','Just once']].map(([v,t])=>`<option value="${v}" ${g.frequency===v?'selected':''}>${t}</option>`).join('')}</select></label>`:field({label:'Covered until',name:'due',type:'date',value:g.due,min:today(),required:true});
    return `<section class="page task-page">${pageHead('Let’s make room')}<div class="content"><h1 class="large-question">${question}</h1>${g.step!=='name'?`<p class="muted" style="margin-bottom:20px">${esc(g.name)}${g.step!=='rate'?` · ${cash(money(g.rateText))} each time`:''}${g.step==='due'?` · ${esc(g.frequency)}`:''}</p>`:'<p class="muted">Food, transport or something else that cannot wait.</p>'}<form id="guided-plan" data-step="${esc(g.step)}" class="form-stack">${input}<p class="error" role="alert"></p><button class="button" type="submit">${g.step==='due'?'Work it out':'Continue'}</button>${g.step!=='name'?'<button class="text-button" type="button" data-parity="guided-back">Previous question</button>':''}</form>${d.lastCalculation?`<p class="notice" style="margin-top:18px">${esc(d.lastCalculation)}</p>`:''}${d.items.length?`<div class="section-label">In your draft</div><div class="panel">${d.items.map(i=>row({emoji:icon(categorySymbol(i.name),20),title:i.name,sub:i.calculation||dateLabel(i.due),right:planningMoney(ctx,i.amount)})).join('')}</div>${actionButton('Review my budget','guided-review')}`:''}</div></section>`;
  }
  return null;
}
function newPeriod(ctx,source=null){
  planningSheet(ctx, `<h2>Make the next period yours.</h2><p>${source?'Reuse this saved plan':'Your current period will be archived'}. Used amounts reset only in the new period.</p><form class="form-stack">${field({label:'Starts',name:'start',type:'date',value:today(),max:today(),required:true})}${field({label:'Plan covers me until',name:'end',type:'date',value:future(30),min:today(),required:true})}<p class="error" role="alert"></p><button class="button">Review fresh plan</button></form>`,el=>{el.querySelector('form').onsubmit=e=>{e.preventDefault();const start=el.querySelector('[name=start]').value,end=el.querySelector('[name=end]').value;if(end<start){el.querySelector('.error').textContent='The end date needs to follow the start.';return;}ctx.draft.plan={items:structuredClone((source||ctx.state.budget).items).map(i=>({...i,spent:0})),item:{},...((source||ctx.state.budget).provenance?{suggestion:structuredClone((source||ctx.state.budget).provenance)}:{}),newPeriod:{startDate:start,endDate:end,...(source?{periodId:source.periodId}:{})}};ctx.closeSheet();ctx.go({section:'plan',page:'create',step:'review'});}});
}
export function openCategoryHabits(ctx){
  const payments=ctx.state.transactions.filter(t=>t.type==='payment'&&t.status==='success').slice(0,50),items=ctx.state.budget.items;
  planningSheet(ctx, `<h2>Make categories feel familiar.</h2><p>Choose where a completed payment belongs. Remember it only when you want to.</p><form class="form-stack"><label>Completed payment<select name="transaction">${payments.map(t=>`<option value="${esc(t.id)}">${esc(t.merchant)} · ${planningMoney(ctx,t.amount)}</option>`).join('')}</select></label><label>Budget category<select name="category">${items.map(i=>`<option value="${esc(i.id)}">${esc(i.name)}</option>`).join('')}</select></label><label><input name="remember" type="checkbox"> Suggest this category for this merchant next time</label><p class="error" role="alert"></p><button class="button" ${!payments.length||!items.length?'disabled':''}>Correct category</button></form><div class="section-label">Remembered choices</div><div class="panel">${(ctx.state.categoryRules||[]).map(r=>`<button class="row" data-forget="${esc(r.merchantKey)}"><span class="row-copy"><strong>${esc(r.merchant)}</strong><small>${esc(r.category)}</small></span><span>Forget</span></button>`).join('')||'<p class="muted" style="padding:16px">No remembered choices yet.</p>'}</div>`,el=>{el.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.currentTarget,r=ctx.act('correctTransactionCategory',{transactionId:f.elements.transaction.value,budgetItemId:f.elements.category.value,remember:f.elements.remember.checked});if(!r.ok){el.querySelector('.error').textContent=r.message;return;}ctx.closeSheet();ctx.refresh();ctx.toast(r.message);};el.querySelectorAll('[data-forget]').forEach(b=>b.onclick=()=>{ctx.act('forgetCategory',{merchant:b.dataset.forget});ctx.closeSheet();openCategoryHabits(ctx);});});
}
export function bindPlanningParity(ctx,r){
  const nodes=ctx.$$('[data-parity], [data-action^="parity-"]'),clean=[];
  const handle=e=>{const b=e.currentTarget,a=b.dataset.parity||b.dataset.action.slice(7),id=b.dataset.id;
    if(a==='hacks')return ctx.go({section:'boxes',page:'hacks'});if(a==='archives')return ctx.go({section:'boxes',page:'archive'});if(a==='periods')return ctx.go({section:'plan',page:'periods'});if(a==='guided')return ctx.go({section:'plan',page:'guided'});if(a==='categories')return openCategoryHabits(ctx);
    if(a==='new-period')return newPeriod(ctx);
    if(a==='archive-period'){ctx.auth({title:'Archive this budget period?',onSuccess:()=>{const result=ctx.act('archiveBudgetPeriod');if(result.ok)ctx.refresh();ctx.toast(result.message);}});return;}
    if(a.startsWith('period-')){const p=ctx.state.budgetHistory.find(p=>p.periodId===a.slice(7));if(!p)return;planningSheet(ctx, `<h2>Your period in review.</h2><p>${dateLabel(p.startDate)} – ${dateLabel(p.endDate)}</p><div class="panel">${p.items.map(i=>row({emoji:icon(categorySymbol(i.name),20),title:i.name,sub:`Planned ${planningMoney(ctx,i.amount)} · Used ${planningMoney(ctx,i.spent)}`,right:planningMoney(ctx,i.amount-i.spent)})).join('')}</div><button class="button" data-reuse>Reuse for a fresh period</button>`,el=>el.querySelector('[data-reuse]').onclick=()=>{ctx.closeSheet();newPeriod(ctx,p);});return;}
    if(a==='guided-back'){const g=ctx.draft.plan.guide,steps=['name','rate','frequency','due'];g.step=steps[Math.max(0,steps.indexOf(g.step)-1)];ctx.refresh();return;}
    if(a==='guided-review')return ctx.go({section:'plan',page:'create',step:'review'});
    if(a==='run-schedules'){const result=ctx.act('runScheduledSavings');ctx.refresh();ctx.toast(result.message);return;}
    if(a.startsWith('restore-')){const result=ctx.act('restoreBox',{id:a.slice(8)});ctx.refresh();ctx.toast(result.message);return;}
    if(a.startsWith('rule-')){const box=ctx.state.boxes.find(x=>x.id===a.slice(5));if(!box)return;planningSheet(ctx, `<h2>${esc(box.name)}</h2><p>${title(box.hack)}${box.hack.paused?' · Paused':''}</p><div class="stack"><button class="button" data-edit>Edit rule</button><button class="button secondary" data-pause>${box.hack.paused?'Resume':'Pause'} this rule</button><button class="text-button" data-cancel>Cancel rule</button></div>`,el=>{el.querySelector('[data-edit]').onclick=()=>openHackEditor(ctx,box);el.querySelector('[data-pause]').onclick=()=>{ctx.act('setHackPaused',{id:box.id,paused:!box.hack.paused});ctx.closeSheet();ctx.refresh();};el.querySelector('[data-cancel]').onclick=()=>{ctx.act('cancelSavingsHack',{id:box.id});ctx.closeSheet();ctx.refresh();};});return;}
    if(a.startsWith('move-')){const t=ctx.state.transactions.find(t=>t.id===a.slice(5));return ctx.go({section:'boxes',page:'transfer',id:a.slice(5),boxId:t?.boxId});}
    if(a==='transfer-open')return ctx.go({section:'boxes',page:'transfer',id});if(a==='transfer-box')return ctx.go({section:'boxes',page:'detail',id});
    if(a==='transfer-check'){ctx.toast('Still pending. Choose a labelled simulation outcome to settle it.');return;}
    const types={'transfer-success':['resolveBoxTransfer',{status:'success'}],'transfer-failed':['resolveBoxTransfer',{status:'failed'}],'transfer-retry':['retryBoxTransfer',{}],'transfer-reverse':['reverseBoxTransfer',{}]};
    if(types[a]){const [type,p]=types[a];ctx.auth({title:'Confirm this simulated transfer update',onSuccess:()=>{const result=ctx.act(type,{transactionId:id,...p,idempotencyKey:`${type}-${id}-${key()}`});ctx.refresh();ctx.toast(result.message);}});}
  };for(const n of nodes){n.addEventListener('click',handle);clean.push(()=>n.removeEventListener('click',handle));}
  const form=ctx.$('#guided-plan');if(form){const submit=e=>{
    e.preventDefault();const f=e.currentTarget,d=ctx.draft.plan,g=d.guide,fail=m=>{form.querySelector('.error').textContent=m;};
    if(g.step==='name'){const name=f.elements.name.value.trim();if(!name)return fail('What should we call this essential?');if(d.items.some(i=>budgetCategoryKey(i.name)===budgetCategoryKey(name)))return fail('That essential is already in your draft. Adjust it in review.');g.name=name.slice(0,60);g.step='rate';}
    else if(g.step==='rate'){const amount=money(f.elements.rate.value);if(!Number.isSafeInteger(amount)||amount<=0||amount>1000000000)return fail('Use an amount above zero, with at most two decimal places.');g.rateText=f.elements.rate.value;g.step='frequency';}
    else if(g.step==='frequency'){g.frequency=f.elements.frequency.value;g.step='due';}
    else{g.due=f.elements.due.value;if(!g.due||g.due<today())return fail('Choose today or a future date.');const days=Math.max(1,Math.ceil((new Date(`${g.due}T12:00:00Z`)-new Date(`${today()}T12:00:00Z`))/86400000)+1),mult=g.frequency==='daily'?days:g.frequency==='weekly'?Math.ceil(days/7):1,rate=money(g.rateText),amount=rate*mult;if(!Number.isSafeInteger(amount)||amount>1000000000)return fail('That total is above the demo limit. Try a smaller amount or shorter period.');const calculation=`${cash(rate)} × ${mult} ${g.frequency==='daily'?'days':g.frequency==='weekly'?'weeks':'time'} = ${cash(amount)}`;d.items.push({id:key(),name:g.name,amount,spent:0,due:g.due,emoji:'📝',calculation});d.lastCalculation=calculation;d.guide={step:'name',name:'',rateText:'',frequency:'weekly',due:g.due};}
    ctx.saveDraft?.();ctx.refresh();
  };form.addEventListener('submit',submit);clean.push(()=>form.removeEventListener('submit',submit));}
  return ()=>clean.forEach(f=>f());
}
export {budgetSuggestions};
